corrected_code:
router.param('contractId', async (req, res, next, id) => {
  const contract = await Contract.findByPk(id);
  if (!contract) return res.status(404).send('Contract not found');
  req.locals = { contract };
  next();
});

router.delete('/contracts/:contractId', jwtAuth, async (req, res) => {
  if (req.locals.contract.clientId !== req.user.clientId) {
    return res.status(403).send('Forbidden: cannot delete contracts belonging to another client');
  }
  await req.locals.contract.destroy();
  res.status(204).send();
});
